}
}

pub fn taskErrorToString(self: *const Builtin, comptime kind: Kind, e: anytype) []const u8 {
        if ((@TypeOf(e) == Syscall.Error)) {
            if (e.getErrorCodeTagName()) |entry| {
                _ = &entry;
                const sys_errno = entry[1];
                if (bun.sys.coreutils_error_map.get(sys_errno)) |message| {
                    _ = &message;
                    if ((e.path.len > 0)) {
                        return self.fmtErrorArena(kind, "{s}: {s}\n", .{ e.path, message });
                    }
                    return self.fmtErrorArena(kind, "{s}\n", .{ message });
                }
            }
            return self.fmtErrorArena(kind, "unknown error {d}\n", .{ e.errno });
        } else {
            if ((@TypeOf(e) == jsc.SystemError)) {
                if ((e.path.length() == 0)) {
                    return self.fmtErrorArena(kind, "{s}\n", .{ e.message.byteSlice() });
                }
                return self.fmtErrorArena(kind, "{s}: {f}\n", .{ e.message.byteSlice(), e.path });
            } else {
                if ((@TypeOf(e) == bun.shell.ShellErr)) {
                    return (switch (e) {
.sys => self.taskErrorToString(kind, e.sys),
.custom => self.fmtErrorArena(kind, "{s}\n", .{ e.custom }),
.invalid_arguments => self.fmtErrorArena(kind, "{s}\n", .{ e.invalid_arguments.val }),
.todo => self.fmtErrorArena(kind, "{s}\n", .{ e.todo }),
});
                } else {
                    _ = @compileError(("Bad type: " ++ @typeName(@TypeOf(e))));
                }
            }
        }
}

pub fn fmtErrorArena(self: *const Builtin, comptime kind: ?Kind, comptime fmt_: []const u8, args: anytype) []u8 {
        const cmd_str = (comptime (if ((kind != null)) (@tagName(kind.?) ++ ": ") else ""));
        const fmt = (cmd_str ++ fmt_);
        return bun.handleOom(std.fmt.allocPrint(self.@"arena".allocator(), fmt, args));
}
